  "Tomates : râpées sans la peau (Cooking With Alia, MarocMama, option chez Taste of Maroc), pelées et hachées (Taste of Maroc) ou en conserve (My Moroccan Food, Amour de cuisine). Retenu : tomates fraîches râpées.",
